function dependencyManifest(schema=false): any {
  return {...(schema?schemaManifest():{format:3,databaseMigrations:false}),
    dependencies:{...REVIEWED_DEPENDENCIES,platform:'linux',arch:'x64',node:'20.19.6',treeSha256:'a'.repeat(64)}};
}
test('private dependencies require the exact reviewed pair and an explicit dependency acknowledgement',()=>{
  const manifest=dependencyManifest();
  const before={package:REVIEWED_DEPENDENCIES.beforePackage,lock:REVIEWED_DEPENDENCIES.beforeLock};
  const after={package:REVIEWED_DEPENDENCIES.afterPackage,lock:REVIEWED_DEPENDENCIES.afterLock};
  assertDependencyTransition(before,after,manifest);
  assert.equal(digest(DEPENDENCY_BEFORE_PACKAGE),before.package);assert.equal(digest(DEPENDENCY_BEFORE_LOCK),before.lock);
  assert.equal(digest(DEPENDENCY_AFTER_PACKAGE),after.package);assert.equal(digest(DEPENDENCY_AFTER_LOCK),after.lock);
  assert.throws(()=>assertDependencyTransition(before,after,{databaseMigrations:false}));
  for(const key of ['package','lock']) {
    assert.throws(()=>assertDependencyTransition({...before,[key]:'0'.repeat(64)},after,manifest));
    assert.throws(()=>assertDependencyTransition(before,{...after,[key]:'0'.repeat(64)},manifest));
  }
  for(const patch of [{id:'other'},{beforeLock:'0'.repeat(64)},{afterLock:'0'.repeat(64)},
    {treeSha256:''},{platform:'darwin'},{arch:'arm64'},{node:'22.14.0'}])assert.throws(()=>dependencies({...manifest,dependencies:{...manifest.dependencies,...patch}}));
  assert.throws(()=>dependencies({...manifest,format:2}));
  assert.equal(requiredAcknowledgement(manifest),'SITREP-HOSTINGER-DEPS');
  assert.equal(requiredAcknowledgement(dependencyManifest(true)),'SITREP-HOSTINGER-SCHEMA-DEPS');
  for(const schema of [true,false]) {
    const item=dependencyManifest(schema);assertAcknowledgement(item,requiredAcknowledgement(item));
    for(const ack of ['SITREP-HOSTINGER','SITREP-HOSTINGER-SCHEMA',''])assert.throws(()=>assertAcknowledgement(item,ack));
  }
});
